import {LESSONS} from './learn-data.js';
import {effects,marketingOutcome} from './engine.js';
import {productDemand} from './progression.js';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='solo-inc-learning-v1';let record={done:[],answers:{},notes:{}};
try{const r=JSON.parse(localStorage.getItem(KEY));if(r&&Array.isArray(r.done)&&r.answers&&typeof r.answers==='object'&&r.notes&&typeof r.notes==='object')record=r}catch{ $('#storage-status').textContent='学习记录暂时无法读取，仍可继续学习。'}
function save(){try{localStorage.setItem(KEY,JSON.stringify(record));$('#storage-status').textContent=''}catch{$('#storage-status').textContent='本次学习记录未能保存到浏览器，请复制笔记留存。'}progress()}
function progress(){const n=LESSONS.filter(x=>record.done.includes(x.id)).length;$('#progress').innerHTML=`已学 ${n} / ${LESSONS.length} 个模块<progress value="${n}" max="${LESSONS.length}"></progress>`}
function nav(){const hash=location.hash.slice(1)||'overview';$('#nav').innerHTML=[['overview','◈ 学习总览'],['lab','⌘ 规则实验室'],['notes','▤ 我的学习笔记']].map(([id,t])=>`<a class="${hash===id?'active':''}" href="#${id}">${t}</a>`).join('')+LESSONS.map((l,i)=>`${i===0||LESSONS[i-1].group!==l.group?`<small>${l.group}</small>`:''}<a class="lesson-nav ${hash===l.id?'active':''}" href="#${l.id}">${String(i+1).padStart(2,'0')} ${l.title.split('：')[0]}</a>`).join('');progress()}
function heading(k,t,d){return `<p class="eyebrow">${k}</p><h1>${t}</h1><p class="intro">${d}</p>`}
function overview(){const next=LESSONS.find(l=>!record.done.includes(l.id))||LESSONS[0];$('#content').innerHTML=heading('LEARN THE SYSTEM','不只会玩，也看懂为什么。','沿着「选择角色 → 获客交付 → 产品增长 → 持续收入」学习游戏。每个模块包含功能说明、实际规则、设计解读与一道自测题。')+`<div class="hero"><div><h2>下一课 · ${next.title.split('：')[0]}</h2><p>${next.desc}</p></div><a class="btn primary" href="#${next.id}">继续学习 →</a></div><label for="search">查找功能或规则</label><br><input class="search" id="search" placeholder="搜索：客户、定价、月薪、LLM…" type="search"><div class="grid" id="cards"></div>`;function cards(){const q=$('#search').value.trim().toLowerCase();const list=LESSONS.filter(l=>JSON.stringify(l).toLowerCase().includes(q));$('#cards').innerHTML=list.length?list.map(l=>`<article class="card"><a href="#${l.id}"><span class="tag">${l.group} · ${record.done.includes(l.id)?'已学完':'待学习'}</span><h3>${l.title}</h3><p>${l.desc}</p><span>进入模块 ↗</span></a></article>`).join(''):'<p class="muted">没有匹配的模块，试试其他关键词。</p>'}$('#search').addEventListener('input',cards);cards()}
const ul=a=>`<ul>${a.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`;
function lesson(l){const i=LESSONS.indexOf(l);$('#content').innerHTML=heading(`${l.group} / MODULE ${String(i+1).padStart(2,'0')}`,l.title,l.desc)+`<div class="lesson-grid"><div><button class="shot-button" id="shot" aria-label="放大界面参考截图"><img class="shot" src="devlog-assets/${l.image}" alt="${l.title}界面参考"></button><p class="caption">界面参考 · 点击放大；历史截图的数值不代表当前新局</p><section class="section"><h2>功能特点</h2>${ul(l.features)}<h3>玩家操作路径</h3><div class="flow">${l.flow.map(x=>`<span>${esc(x)}</span>`).join('')}</div></section><section class="section"><h2>为什么这样设计</h2><span class="tag">设计解读</span><p>${esc(l.logic)}</p><h3>边界与取舍</h3><p>${esc(l.edge)}</p></section><section class="section"><h2>检验理解</h2><p>${esc(l.question)}</p><div class="question-options">${l.options.map((x,n)=>`<button data-answer="${n}">${'ABC'[n]} · ${esc(x)}</button>`).join('')}</div><div id="feedback" role="status"></div></section></div><div><section class="section" style="margin-top:0"><h2>学完你会知道</h2>${ul(l.goals)}</section><section class="section"><h2>当前规则</h2><span class="tag">代码中的实际规则</span>${ul(l.rules)}<a class="btn" href="#lab">进入规则实验室 ↗</a></section><section class="section"><h2>实现线索</h2>${l.source.map(s=>`<p class="source">${esc(s)}</p>`).join('')}<a class="btn" href="devlog.html#step-${l.step}">查看相关 Prompt 与截图 ↗</a></section><section class="section"><h2>我的理解</h2><label class="caption" for="note">记录设计启发或想调整的规则，自动保存在本浏览器。</label><textarea class="note" id="note" placeholder="例如：为什么把联系人和订单分开？">${esc(record.notes[l.id]||'')}</textarea></section></div></div><div class="pager"><button class="primary" id="complete">${record.done.includes(l.id)?'已学完 · 取消标记':'标记为已学完 ✓'}</button>${i>0?`<a class="btn" href="#${LESSONS[i-1].id}">← 上一课</a>`:''}${i<LESSONS.length-1?`<a class="btn" href="#${LESSONS[i+1].id}">下一课 →</a>`:'<a class="btn" href="#overview">返回总览</a>'}</div>`;
function feedback(a){document.querySelectorAll('[data-answer]').forEach(b=>b.classList.toggle('selected',+b.dataset.answer===a));$('#feedback').innerHTML=`<p class="feedback">${a===l.answer?'✓ 理解正确':'再想一想'} · ${esc(l.explain)}</p>`}
document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{record.answers[l.id]=+b.dataset.answer;save();feedback(+b.dataset.answer)});if(Number.isInteger(record.answers[l.id]))feedback(record.answers[l.id]);$('#note').oninput=e=>{record.notes[l.id]=e.target.value;save()};$('#complete').onclick=()=>{record.done=record.done.includes(l.id)?record.done.filter(x=>x!==l.id):[...record.done,l.id];save();lesson(l)};$('#shot').onclick=()=>{$('#zoom img').src=`devlog-assets/${l.image}`;$('#zoom').showModal()}}
function slider(id,label,value,max=100,min=0,step=1){return `<label class="control"><span>${label}<output for="${id}" id="${id}-value">${value}</output></span><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`}
function lab(){$('#content').innerHTML=heading('RULES LAB','动手调一调，理解因果。','以下调用游戏现有的纯计算函数，使用独立示例参数，不读取或修改经营存档，也不调用模型。')+`<div class="lab-grid"><section class="section"><h2>01 / 交付产能</h2><p class="muted">一次行动如何推进项目？</p>${slider('delivery','交付能力',45)}${slider('energy','行动前精力',90)}<label><input id="templates" type="checkbox"> 已购买交付模板</label><div class="result" id="delivery-result"></div><p class="caption">标准工作量不是现实时间。无论推进多少，本次行动仍占用 8 小时、一个时段。</p></section><section class="section"><h2>02 / 产品销售</h2><p class="muted">固定参数下的 28 天推演</p>${slider('reach','累计触达',600,3000)}${slider('fit','评估匹配度 / 当前匹配度',80)}${slider('conversion','评估转化价值',80)}${slider('reputation','信誉',30)}${slider('price','产品定价（元）',199,1000,1)}<div class="result" id="sales-result"></div><p class="caption">假定产品已上线，初始小数订单余量为零，每天参数不变。累计小数需求再结算整数订单；实际经营中的增长、定价调整和记录重置会改变结果。</p></section><section class="section"><h2>03 / 内容获客</h2><p class="muted">文章质量如何影响结果？</p>${slider('content-skill','内容创作能力',60)}${slider('relevance','需求相关度',80)}${slider('usefulness','实用性',80)}${slider('trust','可信度',80)}<div class="result" id="marketing-result"></div><p class="caption">评分由模型对文章独立评估；此处手动设分以学习规则。咨询量还受实际通讯录容量影响，不等于签约客户。</p></section></div>`;
function calc(){const n=id=>+$('#'+id).value;document.querySelectorAll('input[type=range]').forEach(x=>$('#'+x.id+'-value').textContent=x.value);const s={skills:{delivery:n('delivery'),insight:50,content:n('content-skill'),outreach:50},tools:$('#templates').checked?['templates']:[]};const output=Math.floor(effects(s).delivery*(n('energy')<25?.5:n('energy')<45?.75:1));$('#delivery-result').innerHTML=`<strong>${output} 标准小时</strong><small>精力效率 ${n('energy')<25?'50%':n('energy')<45?'75%':'100%'}</small>`;const demand=productDemand({product:100,productPlan:{price:n('price')},productEvaluation:{fit:n('fit'),conversion:n('conversion')},productFit:n('fit'),reach:n('reach'),reputation:n('reputation')});let carry=0,orders=0,positive=0;for(let day=0;day<28;day++){carry+=demand;const count=Math.floor(carry);carry-=count;orders+=count;if(count>0)positive++}$('#sales-result').innerHTML=`<strong>¥${(orders*n('price')).toLocaleString('zh-CN')}</strong><small>每日理论需求 ${demand.toFixed(2)} 单</small><small>28 天累计 ${orders} 单 · ${positive} 天有收入</small>`;const m=marketingOutcome(s,{relevance:n('relevance'),usefulness:n('usefulness'),trust:n('trust'),feedback:'学习示例'});$('#marketing-result').innerHTML=`<strong>+${m.reach} 触达</strong><small>综合质量 ${m.quality} / 100 · ${m.inquiries} 条咨询</small><small>信誉 ${m.reputation>0?'+':''}${m.reputation}</small>`}document.querySelectorAll('input').forEach(x=>x.oninput=calc);calc()}
function notes(){const saved=LESSONS.filter(l=>String(record.notes[l.id]||'').trim());$('#content').innerHTML=heading('MY NOTES','把理解留在这里。','笔记与学习进度保存在当前浏览器，与游戏角色存档独立。清理浏览器数据会删除记录，可导出留存。')+`<button id="export" class="primary">导出学习笔记</button><div class="grid">${saved.length?saved.map(l=>`<article class="card"><a href="#${l.id}"><h3>${l.title}</h3></a><p style="white-space:pre-wrap">${esc(record.notes[l.id])}</p></article>`).join(''):'<p class="muted">还没有笔记。进入任意课程，在「我的理解」中开始记录。</p>'}</div>`;$('#export').onclick=()=>{const text=LESSONS.map(l=>`${record.done.includes(l.id)?'✓':'○'} ${l.title}\n${record.notes[l.id]||'（暂无笔记）'}`).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='一人公司模拟器-学习笔记.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
function render(){nav();const id=location.hash.slice(1)||'overview',l=LESSONS.find(x=>x.id===id);if(l)lesson(l);else if(id==='lab')lab();else if(id==='notes')notes();else overview();window.scrollTo(0,0)}
$('#close-zoom').onclick=()=>$('#zoom').close();window.addEventListener('hashchange',render);render();
